layers.vertex:
attribute vec3 aO; attribute float aT, aR, aY; uniform float uTime; varying vec2 vL; varying float vH, vF, vP;
    void main(){ float u = uTime - aT; if (u < 0. || uTime - aR > .15){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float hold = min(u, aR - aT); vH = clamp(hold/1.2, 0., 1.);
      vF = (1. - smoothstep(0., .15, uTime - aR))*smoothstep(0., .08, u);
      vP = hold >= 1.2 ? max(0., 1. - (hold - 1.2)/.25) : 0.;           // one blink when fully shaped
      vec2 q = position.xy*19.; float c = cos(aY), s = sin(aY);
      vL = vec2(q.x, q.y);                                                     // local: x right, y forward
      vec3 W = aO + vec3(q.x*c - q.y*s, .03, -q.x*s - q.y*c);
      gl_Position = projectionMatrix*viewMatrix*vec4(W, 1.); }

layers.fragment:
uniform vec3 uDot, uDotL; varying vec2 vL; varying float vH, vF, vP;
    void main(){
      float r = length(vL), a = atan(vL.x, vL.y), A = mix(.44, 0., vH), R = mix(9., 18., vH);
      float near = smoothstep(.6, 1.6, r), inR = smoothstep(R + .05, R - .05, r), inA = smoothstep(A + .01, A - .01, abs(a));
      float edge = exp(-pow((abs(a) - A)*r/mix(.05, .08, vH*vH), 2.))*inR*near*(1. + .6*vH*vH);   // the two borders (one line at the end)
      float arc = exp(-pow((r - R)/.06, 2.))*inA;                              // the range line
      float fill = inA*inR*near*smoothstep(R*.35, R, r)*.07;                   // faint, open centre
      float lum = (edge*.55 + arc*.45 + fill)*(.7 + .3*vH)*(1. + 1.5*vP);
      vec3 o = mix(uDot, uDotL, .25)*lum*vF*.8;
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }
